    public function getHapusPelayanan(Request $request)
    {
        $data = \DB::table('pasiendaftar_t as pd')
            ->leftJoin('pasien_m as p', 'p.id', '=', 'pd.nocmfk')
            ->leftJoin('antrianpasiendiperiksa_t as apd', 'apd.noregistrasifk', '=', 'pd.norec')
            ->leftJoin('pelayananpasiendelete_t as ppd', 'ppd.noregistrasifk', '=', 'apd.norec')
            ->leftJoin('ruangan_m as ru', 'ru.id', '=', 'apd.objectruanganfk')
            ->leftJoin('produk_m as prdk', 'prdk.id', '=', 'ppd.produkfk')
            ->leftJoin('loginuser_s as lgu', 'lgu.id', '=', 'ppd.objectloginuserfk')
            ->select('p.nocm', 'p.namapasien', 'pd.noregistrasi', 'prdk.namaproduk', 'ppd.harganetto AS harga', 'ppd.jasa AS hargajasa', 'ppd.jumlah', 'ppd.tglhapus', 'lgu.namauser', 'ru.namaruangan')
            ->where('pd.statusenabled', true)
            ->where('ppd.statusenabled', true);


        if (isset($request['tglAwal']) && $request['tglAwal'] != "" && $request['tglAwal'] != "undefined") {
            $data = $data->where('apd.tglregistrasi', '>=', $request['tglAwal']);
        }
        if (isset($request['tglAkhir']) && $request['tglAkhir'] != "" && $request['tglAkhir'] != "undefined") {
            $data = $data->where('apd.tglregistrasi', '<=', $request['tglAkhir']);
        }

        // $filter = $request->all();
        // if(isset($filter['noReg']) && $filter['noReg']!="" && $filter['noReg']!="undefined"){
        //     $data = $data->where('pd.noregistrasi','ilike', '%'.$filter['noReg'].'%');
        // }
        // if (isset($filter['jmlRows']) && $filter['jmlRows'] != "" && $filter['jmlRows'] != "undefined") {
        //     $data = $data->take($filter['jmlRows']);
        // }
        $data = $data->distinct();
        $data = $data->get();

        $result = array();
        foreach ($data as $item) {
            $result[] = array(
                'nocm' => $item->nocm,
                'namapasien' => $item->namapasien,
                'noregistrasi' => $item->noregistrasi,
                'namaproduk' => $item->namaproduk,
                'harga' => $item->harga,
                'hargajasa' => $item->hargajasa,
                'jumlah' => $item->jumlah,
                'tglhapus' => $item->tglhapus,
                'namauser' => $item->namauser,
                'namaruangan' => $item->namaruangan,
            );
        }
        return $this->respond($result);
    }
    public function getKaryawanIsoman(Request $request)
    {
        $data1 = [];
        $tglAwal = $request['tglAwal'];
        $pekerjaan = '';
        if (isset($request['pekerjaan']) && $request['pekerjaan'] != "" && $request['pekerjaan'] != "undefined") {
            $ruangId = ' AND psi.objectpekerjaanfk = ' . $request['pekerjaan'];
        }
        $data = DB::select(DB::raw("SELECT        ROW_NUMBER() OVER (ORDER BY  psi.namapasien) AS no, psi.namapasien, CASE WHEN ps.pangkatpolisi IS NOT NULL THEN pkt.namapangkat WHEN ps.pangkatpns IS NOT NULL THEN pkt.namapangkat ELSE '-' END AS pangkat, 
        CASE WHEN psi.objectpekerjaanfk = 6 THEN '1' ELSE '0' END AS polri, CASE WHEN psi.objectpekerjaanfk = 128 THEN '1' ELSE '0' END AS pns, 
        CASE WHEN psi.objectpekerjaanfk = 43 THEN '1' WHEN psi.objectpekerjaanfk = 126 THEN '1' ELSE '0' END AS ptt, CASE WHEN ps.objectjeniskelaminfk = '1' THEN '1' ELSE '0' END AS pria, 
        CASE WHEN ps.objectjeniskelaminfk = '2' THEN '1' ELSE '0' END AS wanita, CASE WHEN psi.objectruanganfk IS NOT NULL THEN ru.namaruangan ELSE '-' END AS ruangankerja, psi.tglisoman, psi.tglselesaiisoman
FROM            ruangan_m AS ru RIGHT OUTER JOIN
        pangkat_m AS pkt RIGHT OUTER JOIN
        pasien_m AS ps ON pkt.id = ps.pangkatpolisi RIGHT OUTER JOIN
        pekerjaan_m AS pk RIGHT OUTER JOIN
        pegawai_m AS pg INNER JOIN
        pasienisoman_t AS psi ON pg.id = psi.idpegawaifk INNER JOIN
        jeniskelamin_m AS jk ON pg.objectjeniskelaminfk = jk.id ON pk.id = psi.objectpekerjaanfk ON ps.id = psi.nocmfk ON ru.id = psi.objectruanganfk
        where psi.tglisoman <= '$tglAwal' and psi.tglselesaiisoman >= '$tglAwal'
        $pekerjaan
        "));
        foreach ($data as $item) {
            $data1[] = array(
                'no' => $item->no,
                'namapasien' => $item->namapasien,
                'pangkat' => $item->pangkat,
                'polri' => (float)$item->polri,
                'pns' => (float)$item->pns,
                'ptt' => (float)$item->ptt,
                'pria' => (float)$item->pria,
                'wanita' => (float)$item->wanita,
                'ruangankerja' => $item->ruangankerja,
                'tglisoman' => $item->tglisoman,
                'tglselesaiisoman' => $item->tglselesaiisoman,
            );
        }
        $result =  array(
            'data' => $data1,
        );

        return $this->respond($result);
    }
    public function getJumlahCovidKaryawan(Request $request)
    {
        $Waktu = '';
        if (isset($request['tglAwal']) && $request['tglAwal'] != "" && $request['tglAwal'] != "undefined") {
            $Waktu = ' AND pds.tglinsertsensus = \'' . $request['tglAwal'] . ':00\' ';
        }

        $data = DB::select(DB::raw("
        select x.pekerjaan,
        sum(pekerjaan2) as jumlah
        from (select ps.namapasien,pd.noregistrasi,ps.nocm,pk.pekerjaan,ps.objectpekerjaanfk, case when ps.objectpekerjaanfk in (6,43,44,126,128) then 1 else 0 end as pekerjaan2
        from pasien_m as ps inner join 
        pasiendaftar_t as pd on pd.nocmfk = ps.id inner join
        pasiendaftarsensus_t as pds on pds.noregistrasifk = pd.norec left join
        pekerjaan_m as pk on pk.id = ps.objectpekerjaanfk inner join
        antrianpasiendiperiksa_t as apd on apd.noregistrasifk = pd.norec and apd.objectruanganfk = pd.objectruanganlastfk inner join
        ruangan_m as ru on ru.id = pd.objectruanganlastfk
        WHERE apd.objectkasuspenyakitfk='19' AND ru.objectdepartemenfk='16' AND pd.tglpulang IS NULL AND pd.statusenabled = '1'
        --AND pds.tglinsertsensus = '2021-07-01 00:00:00'
        $Waktu
        AND ps.objectkaryawanrsfk = '1'
		and ps.objectpekerjaanfk in (6,43,44,126,128)) as x
        group by x.pekerjaan
        "));

        return $this->respond($data);
    }
    public function getJumlahIsomanKaryawan(Request $request)
    {
        $tglAwal = $request['tglAwal'];
        $data = DB::select(DB::raw("
        select x.pekerjaan,
        sum(pekerjaan2) as jumlah
        from (select ps.namapasien,ps.nocm,pk.pekerjaan,psi.objectpekerjaanfk, case when psi.objectpekerjaanfk in (6,43,44,126,128) then 1 else 0 end as pekerjaan2
        from pasien_m as ps right join 
		pasienisoman_t as psi on psi.nocmfk = ps.id left join
        pekerjaan_m as pk on pk.id = psi.objectpekerjaanfk 
        WHERE psi.tglisoman <= '$tglAwal' and psi.tglselesaiisoman >= '$tglAwal'
		and psi.objectpekerjaanfk in (6,43,44,126,128)
		) as x
        group by x.pekerjaan
        "));

        return $this->respond($data);
    }
