    public function getLaporanCovidKaryawan(Request $request)
    {
        ini_set('max_execution_time', 500); //6 minuts
        $data10 = [];
        $asd = '';
        $paramsTgl = 'pp.tglpelayanan';

        $ruangId = '';
        if (isset($request['statRuangan']) && $request['statRuangan'] != "" && $request['statRuangan'] != "undefined") {
            $ruangId = ' AND pd.objectruanganlastfk = ' . $request['statRuangan'];
        }
        $Waktu = '';
        if (isset($request['tglAwal']) && $request['tglAwal'] != "" && $request['tglAwal'] != "undefined") {
            $Waktu = ' AND pds.tglinsertsensus = \'' . $request['tglAwal'] . ':00\' ';
        }
        $pekerjaan = '';
        if (isset($request['pekerjaan']) && $request['pekerjaan'] != "" && $request['pekerjaan'] != "undefined") {
            $ruangId = ' AND ps.objectpekerjaanfk = ' . $request['pekerjaan'];
        }

        $data = DB::select(DB::raw("SELECT distinct ROW_NUMBER() OVER (ORDER BY pd.noregistrasi) AS no, ps.namapasien, pd.noregistrasi, ps.noidentitas, ps.nocm, pd.objectrekananfk, kst.kesatuanpasien, pd.tglregistrasi, pd.tglpulang, ps.nip, ps.nrp,
        CASE WHEN ps.objectpekerjaanfk IN (6,128) THEN '1' ELSE '0' END as polri,
        CASE WHEN ps.objectpekerjaanfk != '6' AND ps.objectpekerjaanfk != '128' THEN '1' ELSE '0' END as umum,
        DATEDIFF(YYYY,ps.[tgllahir], GETDATE()) as umur, ru.namaruangan,
        CASE WHEN ps.objectjeniskelaminfk = '1' THEN '1' ELSE '0' END AS pria, 
        CASE WHEN ps.objectjeniskelaminfk = '2' THEN '1' ELSE '0' END AS wanita, 
        CASE WHEN pd.tglmeninggal IS NOT NULL THEN '1' ELSE '0' END AS meninggal, 
        CASE WHEN pd.tglmeninggal IS NULL THEN '1' ELSE '0' END AS hidup,
        CASE WHEN pkt.namapangkat IS NOT NULL THEN pkt.namapangkat ELSE '-' END AS namapangkat,
        CASE WHEN ps.objectpekerjaanfk = 6 THEN '1' ELSE '0' END AS polri,
        CASE WHEN ps.objectpekerjaanfk = 43 THEN '1' 
             WHEN ps.objectpekerjaanfk = 126 THEN '1'
             WHEN ps.objectpekerjaanfk = 44 THEN '1' ELSE '0' END AS ptt,
        CASE WHEN ps.objectpekerjaanfk = 128 THEN '1' ELSE '0' END AS pns,
        apd.tglmasuk,
        CASE WHEN pg.objectruangankerjafk is not null then ru2.namaruangan else '-' end as ruangankerja,
        CASE WHEN pd.tglpulang is not null then convert (varchar,pd.tglpulang,120) else 'Masih Dirawat' end as tglpulang
        FROM pasien_m as ps
        inner join pasiendaftar_t as pd on pd.nocmfk = ps.id
        inner join pasiendaftarsensus_t as pds on pds.noregistrasifk = pd.norec
        left outer join pangkat_m as pkt on pkt.id = ps.pangkatpolisi
        left outer join kesatuanpasien_m as kst on kst.id = ps.objectkesatuanfk
        inner join antrianpasiendiperiksa_t as apd on apd.noregistrasifk = pd.norec and apd.objectruanganfk = pd.objectruanganlastfk
        inner join ruangan_m as ru on ru.id = pd.objectruanganlastfk
        left join pekerjaan_m as pk on pk.id = ps.objectpekerjaanfk
        left join pegawai_m as pg on pg.nocm = ps.nocm
        left join ruangan_m as ru2 on ru2.id = pg.objectruangankerjafk
        WHERE apd.objectkasuspenyakitfk='19' AND ru.objectdepartemenfk='16' AND pd.tglpulang IS NULL AND pd.statusenabled = '1' AND ps.objectkaryawanrsfk = '1'
        $ruangId $Waktu $pekerjaan
        ORDER BY pd.noregistrasi"));
        foreach ($data as $item) {


            $data10[] = array(
                'tglregistrasi' => $item->tglregistrasi,
                'noregistrasi' => $item->noregistrasi,
                'namaruangan' => $item->namaruangan,
                'namapasien' => $item->namapasien,
                'noidentitas' => $item->noidentitas,
                'nocm' => $item->nocm,
                // 'polri'=>(float)$item->polri,
                // 'pns'=>$item->pns,
                // 'umum'=>(float)$item->umum,
                'namapangkat' => $item->namapangkat,
                // 'nip'=>$nip,
                // 'kesatuanpasien'=>$item->kesatuanpasien,
                'pria' => (float)$item->pria,
                'wanita' => (float)$item->wanita,
                'no' => $item->no,
                'tglrawat' => $item->tglmasuk,
                'polri' => (float)$item->polri,
                'pns' => (float)$item->pns,
                'ptt' => (float)$item->ptt,
                'tglpulang' => $item->tglpulang,
                'ruangankerja' => $item->ruangankerja,
            );
        }

        $result =  array(
            'data' => $data10,
        );
        return $this->respond($result);
    }

