    public function getLaporanCovidVentilator(Request $request)
    {
        ini_set('max_execution_time', 500); //6 minuts
        $data10 = [];
        $a = $request['noregistrasis'];
        $array = explode('-', $a);
        foreach ($array as $data) {
            $datav = DB::select(DB::raw("SELECT pd.noregistrasi, apd.tglmasuk,
            CASE WHEN prd.namaexternal IS NOT NULL THEN prd.namaexternal ELSE '-' END as namatindakan
            FROM pasiendaftar_t as pd
            inner join antrianpasiendiperiksa_t as apd on apd.noregistrasifk = pd.norec
            inner join pelayananpasien_t as pp on pp.noregistrasifk = apd.norec
            inner join produk_m as prd on prd.id = pp.produkfk
            WHERE pd.noregistrasi = $data AND pp.produkfk IN ('4052073','4052074','4052134','4052446','4052449','4052450','4052802','4052803','4052853','4052865' LIMIT 1)     
            -- WHERE pd.noregistrasi = $data AND prd.namaexternal ilike '%ventilator%'
            "));


            if ($datav == null) {
                $venti = '-';
            } else {
                $venti = $datav[0]->namatindakan;
            }

            $data10[] = array(
                'namatindakan' => $venti
            );
        }


        $result = array(
            'data' => $data10,
            'message' => 'egie@epic'
        );
        return $this->respond($result);
    }

    public function getLaporanCovidDiagnosa(Request $request)
    {
        ini_set('max_execution_time', 500); //6 minuts
        $data10 = [];
        $a = $request['noregistrasis'];
        $array = explode('-', $a);
        foreach ($array as $data) {
            $datah = DB::select(DB::raw("SELECT pd.noregistrasi, apd.tglmasuk, jd.id as idjd,
            CASE WHEN dg.namadiagnosa IS NOT NULL THEN dg.namadiagnosa ELSE '-' END as namadiagnosa
            FROM pasiendaftar_t as pd
            inner join antrianpasiendiperiksa_t as apd on apd.noregistrasifk = pd.norec
            left outer join diagnosapasien_t as dp on dp.noregistrasifk=apd.norec
            left outer join detaildiagnosapasien_t as ddp on ddp.objectdiagnosapasienfk=dp.norec
            left outer join diagnosa_m as dg on dg.id=ddp.objectdiagnosafk
            left outer join jenisdiagnosa_m as jd on jd.id=ddp.objectjenisdiagnosafk
            WHERE pd.noregistrasi = $data
            "));

            $namadiagnosa = '-';
            $namadiagnosas = '-';

            foreach ($datah as $itemh) {
                if ($itemh->idjd == 1) {
                    $namadiagnosa = $itemh->namadiagnosa;
                }
                if ($itemh->idjd == 2) {
                    $namadiagnosas = $itemh->namadiagnosa;
                }
            }

            $data10[] = array(
                'diagnosa' => $namadiagnosa,
                'diagnosas' => $namadiagnosas,
            );
        }


        $result = array(
            'data' => $data10,
            'message' => 'egie@epic'
        );
        return $this->respond($result);
    }

    public function getLaporanCovidHasilLab(Request $request)
    {
        ini_set('max_execution_time', 500); //6 minuts
        $data10 = [];
        $a = $request['noregistrasis'];
        $array = explode('-', $a);
        foreach ($array as $data) {
            $datat = DB::select(DB::raw("SELECT TOP(1) pd.noregistrasi, prd.namaproduk, hh.tglhasil, pp.tglpelayanan,
            CASE WHEN hh.hasil ilike '%posi%' THEN '1' ELSE '0' END as positif, 
            CASE WHEN hh.hasil ilike '%nega%' THEN '1' ELSE '0' END as negatif
            FROM pasiendaftar_t as pd
            inner join antrianpasiendiperiksa_t as apd on apd.noregistrasifk = pd.norec
            inner join pelayananpasien_t as pp on pp.noregistrasifk = apd.norec
            inner join produk_m as prd on prd.id = pp.produkfk
            inner join hasillaboratorium_t as hh on hh.norecpelayanan = pp.norec
            WHERE pd.noregistrasi = $data AND prd.id IN ('4057026','4057027','4057032','4057035','4057036','4057128','4057129','4074947','4054136','4054139','4056864','4057026','4057027','4057032','4057035','4057130','4057131','4074833')            
            ORDER BY hh.tglhasil DESC
            "));

            if ($datat == null) {
                $namaproduk = '';
                $tglpelayanan = '';
                $tglhasil = '';
                $positif = 0;
                $negatif = 0;
            } else {
                $namaproduk = $datat[0]->namaproduk;
                $tglhasil = $datat[0]->tglhasil;
                $positif = $datat[0]->positif;
                $negatif = $datat[0]->negatif;
                $tglpelayanan = $datat[0]->tglpelayanan;
            }

            $data10[] = array(
                'namaproduk' => $namaproduk,
                'tglhasil' => $tglhasil,
                'positif' => (float)$positif,
                'negatif' => (float)$negatif,
                'tglpelayanan' => $tglpelayanan,
            );
        }


        $result = array(
            'data' => $data10,
            'message' => 'egie@epic'
        );
        return $this->respond($result);
    }

