    public function uploadDokumen(Request $request)
    {
        \DB::beginTransaction();
        try {
            $dataLogin = $request->all();
            $dataDPM  = DokumenPasienMaster::where('nocmfk',$request['nocmfk'])
                        ->where('objectjenisdokumencasemix',$request['objectjenisdokumencasemix'])->first();
            if(!empty($dataDPM)){
                $dataDPM->statusenabled = true;
                $dataDPM->namafile = $request['namafile'];
                $dataDPM->uploadfile = "data:image/png;base64,".$request['base64File'];
                $dataDPM->tgldokumen = $request['tglDokumen'];
                $dataDPM->tglupload = $this->getDateTime()->format('Y-m-d H:i:s');
                $dataDPM->iduserupload = $dataLogin['userData']['id'];
                $dataDPM->save();
            }else{
                $dataDPM = new DokumenPasienMaster();
                $dataDPM->norec = $dataDPM->generateNewId();
                $dataDPM->statusenabled = true;
                $dataDPM->nocmfk = $request['nocmfk'];
                $dataDPM->namafile = $request['namafile'];
                $dataDPM->uploadfile = "data:image/png;base64,".$request['base64File'];
                $dataDPM->objectjenisdokumencasemix = $request['objectjenisdokumencasemix'];
                $dataDPM->tgldokumen = $request['tglDokumen'];
                $dataDPM->tglupload = $this->getDateTime()->format('Y-m-d H:i:s');
                $dataDPM->iduserupload = $dataLogin['userData']['id'];
                $dataDPM->save();
            }

            $nocmfk = $request['nocmfk'];
            $data =  DB::select(DB::raw("select dpm.uploadfile,jdc.reportdisplay from dokumenpasienmaster_t as dpm
                INNER JOIN jenisdokumencasemix_m as jdc on jdc.id=dpm.objectjenisdokumencasemix 
                where dpm.nocmfk = $nocmfk and jdc.kodeexternal='norm'
            "));
            
            

            $transStatus = 'true';
            $transMessage = 'Data Berhasil Di Upload';
        } catch (\Exception $e) {
            $transStatus = 'false';
            $transMessage = 'Data Gagal Di Upload';
        };

        if ($transStatus == 'true') {
            DB::commit();
            $result = array(
                "status" => 201,
                "message" => $transMessage,
                "data" => $data
            );
        } else {
            DB::rollBack();
            $result = array(
                "status" => 400,
                "message" => $transMessage,
            );
        }
        return $this->setStatusCode($result['status'])->respond($result, $transMessage);
    }
