                $dataDPM->objectjenisdokumencasemix = $request['objectjenisdokumencasemix'];
                $dataDPM->tgldokumen = $request['tglDokumen'];
                $dataDPM->tglupload = $this->getDateTime()->format('Y-m-d H:i:s');
                $dataDPM->iduserupload = $dataLogin['userData']['id'];
                $dataDPM->save();
            }

            $noregistrasi = $request['noregistrasi'];
            $data =  DB::select(DB::raw("select dpm.uploadfile,jdc.reportdisplay from dokumenpasienregistrasi_t as dpm
                INNER JOIN jenisdokumencasemix_m as jdc on jdc.id=dpm.objectjenisdokumencasemix 
                where dpm.noregistrasi = '$noregistrasi' and jdc.kodeexternal='noregistrasi'
            "));
            
            

            $transStatus = 'true';
            $transMessage = 'Data Berhasil Di Upload';
        } catch (\Exception $e) {
            $transStatus = 'false';
            $transMessage = 'Data Gagal Di Upload';
        };

        if ($transStatus == 'true') {
            DB::commit();
            $result = array(
                "status" => 201,
                "message" => $transMessage,
                "data" => $data
            );
        } else {
            DB::rollBack();
            $result = array(
                "status" => 400,
                "message" => $transMessage,
            );
        }
        return $this->setStatusCode($result['status'])->respond($result, $transMessage);
    }
    public function getTindakanPenunjang(Request $request)
    {
        $data = \DB::table('mapruangantoproduk_m as mrp')
            // ->join('pegawai_m as pg','pg.id','=','lg.objectpegawaifk')
            ->select('mrp.objectprodukfk')
            // ->where('pg.id', $request['pegawaiid'])
            ->whereIn('mrp.objectruanganfk', [41, 575, 576])
            ->where('mrp.statusenabled', true)
            // ->whereIn('mrp.objectprodukfk', $tindakan2)
            ->get();

        return $this->respond($data);
    }
    public function getMapRuanganUser(Request $request)
    {
        $data = \DB::table('maploginusertoruangan_s as mlu')
            ->join('loginuser_s as lg', 'lg.id', '=', 'mlu.objectloginuserfk')
            ->join('pegawai_m as pg', 'pg.id', '=', 'lg.objectpegawaifk')
            ->leftjoin('ruangan_m as ru', 'ru.id', '=', 'mlu.objectruanganfk')
            ->select('lg.id as loginuser', 'mlu.objectruanganfk', 'ru.namaruangan', 'pg.namalengkap')
            ->where('pg.id', $request['pegawaiid'])
            ->get();

        return $this->respond($data);
    }
