    public function saveRencanaKontrol(Request $request)
    {
        DB::beginTransaction();
        // return($request['nosuratkontrol']);
        // die();
        try {
           

            $data = PasienDaftar::where('norec', $request['noregistrasifk'])
                    ->update([
                        'generatesuratkontrol' => $request['nosuratkontrol']
                    ]);

            $transStatus = 'true';
            $transMessage = "Simpan Surat Kontrol berhasil!";
        } catch (\Exception $e) {
            $transStatus = 'false';
            $transMessage = "Simpan Surat Kontrol Gagal!";
        }

        if ($transStatus != 'false') {
            DB::commit();
            $result = array(
                "status" => 201,
                "data" => $data,
                "message" => $transMessage,
            );
        } else {
            DB::rollBack();
            $result = array(
                "status" => 400,
                "message" => $transMessage,
            );
        }

        return $this->setStatusCode($result['status'])->respond($result, $transMessage);
    }
    function addAntrianMJKN($request){
        $data = $this->getIdConsumerAntrol();
        $secretKey = $this->getPasswordConsumerAntrol();
        $userKey = $this->getUserKeyAntrol();
        // Computes the timestamp
        date_default_timezone_set('UTC');
        $tStamp = strval(time()-strtotime('1970-01-01 00:00:00'));
        // Computes the signature by hashing the salt with the secret key as the key
        $signature = hash_hmac('sha256', $data."&".$tStamp, $secretKey, true);
        // return($request['data']);
        // die();
        // base64 encode…
        $encodedSignature = base64_encode($signature);
            $curl = curl_init();
            $dataJsonSend = json_encode($request['data']);
            curl_setopt_array($curl, array(
                CURLOPT_PORT =>  $this->getPortBrigdingBPJS(),
                CURLOPT_URL => $this->getUrlBrigdingAntrol()."antrean/add",
                CURLOPT_RETURNTRANSFER => true,
                CURLOPT_SSL_VERIFYHOST => 0,
                CURLOPT_SSL_VERIFYPEER => 0,
                CURLOPT_ENCODING => "",
                CURLOPT_MAXREDIRS => 10,
                CURLOPT_TIMEOUT => 30,
                CURLOPT_HTTP_VERSION => CURL_HTTP_VERSION_1_1,
                CURLOPT_CUSTOMREQUEST => "POST",
                CURLOPT_POSTFIELDS => $dataJsonSend,
                CURLOPT_HTTPHEADER => array(
                    "Content-Type: Application/x-www-form-urlencoded",
                    "X-cons-id: ".  (string)$data,
                    "X-signature: ". (string)$encodedSignature,
                    "X-timestamp: ". (string)$tStamp,
                    "user_key:".$userKey
                ),
                CURLOPT_SSL_CIPHER_LIST => 'DEFAULT@SECLEVEL=1'
            ));

            $response = curl_exec($curl);
            $err = curl_error($curl);

            curl_close($curl);

            if ($err) {
                $result= "cURL Error #:" . $err;
            } else {
                $result = (array) json_decode($response);
            }
            $new = new SendTaskAntrol();
            $new->norec =  $new->generateNewId();
            $new->noreservasi = $request['data']['kodebooking'];
            date_default_timezone_set("Asia/Jakarta");
            $new->tglinsert = date('Y-m-d H:i:s');
            $new->response = $response;
            $new->request =  json_encode($request['data']);
            $new->save();
        return($result);
    }
    public function savePisahFakturBedaInstalasi(Request $request)
    {
        $noRegistrasiBaru = $this->generateCodeBySeqTable(new PasienDaftar, 'noregistrasi', 10, date('ym'));
        if ($noRegistrasiBaru == '') {
