            // $dataapd = AntrianPasienDiperiksa::where('norec', $item)->get();
        }
        $dataapd = AntrianPasienDiperiksa::whereIn('norec', $norecapd)
            ->update(array('noregistrasifk' => $dataPDnorec));
        // return($dataapd);
