    public function saveDokterMelayani(Request $request)
    {
        DB::beginTransaction();
        try {

            if ($request['data']['noregistrasi'] != 'null' || $request['data']['noregistrasi'] != 'undefined') {
                $norec = PasienDaftar::where('noregistrasi', $request['data']['noregistrasi'])
                    ->select(DB::raw("norec"))
                    ->get();
                foreach ($norec as $item) {
                    $data2 = PemakaianAsuransi::where('noregistrasifk', $item->norec)
                        ->update([
                            'kodedpjpmelayani' => $request['data']['kodedpjpmelayani'],
                            'namadjpjpmelayani' => $request['data']['namadjpjpmelayani']
                        ]);

                    $transStatus = 'true';
                    $transMessage = "Simpan Asuransi Pasien";
                    DB::commit();
                    $result = array(
                        'status' => 201,
                        'message' => $transMessage,
                        'as' => 'er@epic',
                    );
                    return $this->setStatusCode($result['status'])->respond($result, $transMessage);
                }
            }

            $transStatus = 'false';
        } catch (\Exception $e) {
            $transStatus = 'false';
        }


        if ($transStatus == 'true') {
            $transMessage = "Simpan Asuransi Pasien";
            DB::commit();
            $result = array(
                'status' => 201,
                'message' => $transMessage,
                'as' => 'er@epic',
            );
        } else {
            $transMessage = "Gagal Simpan Asuransi Pasien";
            DB::rollBack();
            $result = array(
                'status' => 400,
                'message'  => $transMessage,
                'as' => 'er@epic',
            );
        }
        return $this->setStatusCode($result['status'])->respond($result, $transMessage);
    }

