                (case when pm.namapasien is null then apr.namapasien else pm.namapasien end) as namapasien, 
                (case when apr.isconfirm=\'true\' then \'Confirm\' else \'Reservasi\' end) as status,
                (case when apr.istelemedicine=\'true\' then \'Telemedicine\' else kps.kelompokpasien end) as kelompokpasien,apd.norec as norec_apd,rk.id as idrekanan, case when pm.nocm is null then pm1.nocm else pm.nocm end as nocm, 
                case when pm.noidentitas is null then pm1.noidentitas else pm.noidentitas end as noidentitas, 
                case when pm.namapasien is null then apr.namapasien else pm.namapasien end as namapasien,
                case when apr.tglcekinjkn is null then \'Belum Chekin\' else \'Sudah Chekin\' end as statuscekin, pd.norec as norec_pd,
                apd.namahafis || \'-\'  || apd.noantrian as noantrianpoli')
            )
            ->where('apr.noreservasi', '<>', '-')
            ->where('apr.statusenabled', true)
            // ->where('apr.objectruanganfk','<>','322')
            // ->where('pd.statusenabled', true)
