                'pdv.pertanyaan15',
                'pdv.jawab15',
                'pdv.pertanyaan16',
                'pdv.jawab16',
                'pdv.kodefaskes',
                'pdv.namafaskes',
                'nv.namavaksin',
                (DB::raw("case when pdv.kedua=1 then 'vaksin kedua' else 'vaksin pertama' end as vaksinke")),
                DB::raw('(case when pdv.objectstatuspulangfk IS NULL and pdv.statusenabled = true then \'Belum Vaksin\' when pdv.statusenabled = 0 and pdv.objectstatuspulangfk IS NULL then \'Batal Vaksin\' when pdv.objectstatuspulangfk = 23 then sp.statuspulang else \'-\' end) as statuspulang')

            );
        // ->where('pdv.statusenabled',true);

        $filter = $request;
        if (isset($filter['tglAwal']) && $filter['tglAwal'] != "" && $filter['tglAwal'] != "undefined") {
            $data = $data->where('pdv.tglvaksin', '>=', $filter['tglAwal'] . " 00:00:00");
        }
        if (isset($filter['tglAkhir']) && $filter['tglAkhir'] != "" && $filter['tglAkhir'] != "undefined") {
            $tgl = $filter['tglAkhir'] . " 23:59:59"; //. " 23:59:59";
            $data = $data->where('pdv.tglvaksin', '<=', $tgl);
        }
        if (isset($filter['ruanganId']) && $filter['ruanganId'] != "" && $filter['ruanganId'] != "undefined") {
            $data = $data->where('ru.id', '=', $filter['ruanganId']);
        }
        if (isset($filter['kdReservasi']) && $filter['kdReservasi'] != "" && $filter['kdReservasi'] != "undefined") {
            $data = $data->where('pdv.noregistrasi', '=', $filter['kdReservasi']);
        }
        if (isset($filter['statusRev']) && $filter['statusRev'] == "Confirm" && $filter['statusRev'] == "Confirm" && $filter['statusRev'] == "Confirm") {
            $data = $data->where('apr.isconfirm', '=', true);
        }
        if (isset($filter['statusRev']) && $filter['statusRev'] == "Reservasi" && $filter['statusRev'] == "Reservasi" && $filter['statusRev'] == "Reservasi") {
            $data = $data->whereNull('apr.isconfirm');
        }
        if (isset($filter['nik']) && $filter['nik'] != "" && $filter['nik'] != "undefined") {
            $data = $data->where('pdv.nik', 'ilike', '%' . $filter['nik'] . '%');
            // ->orWhere('apr.namapasien','ilike','%'. $filter['namapasienapr'] .'%');
        }
        if (isset($filter['istelemedicine']) && $filter['istelemedicine'] == "true") {
            $data = $data->whereNotNull('apr.istelemedicine');
        }

        if (isset($filter['tglInput']) && $filter['tglInput'] != "" && $filter['tglInput'] != "undefined") {
            $data = $data->where('apr.tglinput', '>=', $filter['tglInput'] . " 00:00:00");
            $tgl = $filter['tglInput'] . " 23:59:59"; //. " 23:59:59";
            $data = $data->where('apr.tglinput', '<=', $tgl);
        }
        if (isset($filter['statuspulang']) && $filter['statuspulang'] == "BelumVaksin" && $filter['statuspulang'] == "BelumVaksin" && $filter['statuspulang'] == "BelumVaksin") {
            $data = $data->whereNull('pdv.objectstatuspulangfk');
            $data = $data->where('pdv.statusenabled', '=', true);
        }
        if (isset($filter['statuspulang']) && $filter['statuspulang'] == "SudahVaksin" && $filter['statuspulang'] == "SudahVaksin" && $filter['statuspulang'] == "SudahVaksin") {
            $data = $data->where('pdv.objectstatuspulangfk', 23);
        }
        if (isset($filter['statuspulang']) && $filter['statuspulang'] == "BatalVaksin" && $filter['statuspulang'] == "BatalVaksin" && $filter['statuspulang'] == "BatalVaksin") {
            $data = $data->where('pdv.statusenabled', '=', false);
        }

        // if(isset($filter['namapasienapr']) && $filter['namapasienapr'] != "" && $filter['namapasienapr'] != "undefined") {
        //     $data = $data->orWhere('apr.namapasien','ilike','%'. $filter['namapasienapr'] .'%');
        // }
        $data = $data->orderBy('pdv.noantrian', 'asc');
        $data = $data->get();

        $result = array(
            'data' => $data,
            'message' => 'cepot',
        );
        return $this->respond($result);
    }

    public function getDiagnosaDaftarAntrian(Request $request)
    {
        $req = $request->all();
        $icdIX = \DB::table('diagnosa_m as dg')
            ->select('dg.id', 'dg.kddiagnosa', 'dg.namadiagnosa', 'dg.kddiagnosa as kdDiagnosa', (DB::raw("id,kddiagnosa||': '||namadiagnosa as diagnosa")))
            ->where('dg.statusenabled', true)
            ->orderBy('dg.kddiagnosa');

        if (
            isset($req['filter']['filters'][0]['value']) &&
            $req['filter']['filters'][0]['value'] != "" &&
            $req['filter']['filters'][0]['value'] != "undefined"
        ) {
            $icdIX = $icdIX
                ->where('dg.namadiagnosa', 'ilike', '%' . $req['filter']['filters'][0]['value'] . '%')
                ->orWhere('dg.kddiagnosa', 'ilike', $req['filter']['filters'][0]['value'] . '%');
        }

        $icdIX = $icdIX->take(10);
        $icdIX = $icdIX->get();

        return $this->respond($icdIX);
    }
