    public function getDaftarBedahPp(Request $request)
    {
        $pelayanan = \DB::table('pasiendaftar_t as pd')
            ->join('pasien_m as ps', 'ps.id', '=', 'pd.nocmfk')
            ->join('antrianpasiendiperiksa_t as apd ', 'apd.noregistrasifk', '=', 'pd.norec')
            ->join('pelayananpasien_t as pp', 'pp.noregistrasifk', '=', 'apd.norec')
            ->join('ruangan_m as ru', 'ru.id', '=', 'apd.objectruanganfk')
            ->join('ruangan_m as ru1', 'ru1.id', '=', 'apd.objectruanganasalfk')
            ->join('produk_m as pr', 'pr.id', '=', 'pp.produkfk')
            ->leftjoin('jeniskelamin_m as jk', 'jk.id', '=', 'ps.objectjeniskelaminfk')
            ->leftjoin('pelayananpasienpetugas_t as ptu', 'ptu.pelayananpasien', '=', 'pp.norec')
            ->leftjoin('pegawai_m as pg1', 'pg1.id', '=', 'ptu.objectpegawaifk')
            ->leftjoin('pegawai_m as pg', 'pg.id', '=', 'pp.objectpegawaipengirimfk')
            ->select(
                'pp.norec as norec_pp',
                'ru.namaruangan as namaruangan',
                'ru1.namaruangan as namaruanganasal',
                'pr.id as produkId',
                'pr.namaproduk',
                'pp.harganetto as hargaNetto',
                'pr.namaproduk as namaProduk',
                'pg.namalengkap as dokterpengirim',
                'pg1.namalengkap as dokterpemeriksa',
                'ps.nocm',
                'ps.objectjeniskelaminfk',
                'jk.jeniskelamin',
                'apd.norec as norec_apd',
                'pp.iscito',
                'pr.namaproduk as produk',
                'pp.produkfk',
                'pd.noregistrasi',
                DB::raw("DATEDIFF(d, ps.tgllahir, GETDATE()) as umur,format(ps.tgllahir,'yyyy-MM-dd HH:mm') as tgllahir,format(pp.tglpelayanan,'yyyy-MM-dd HH:mm') as tglpelayanan")
            )
            ->where('pd.noregistrasi', $request['noregistrasi'])
            ->where('pp.isbedah', true);
        $pelayanan = $pelayanan->get();

        // return($pelayanan);
        // die();
        $result = [];

        foreach ($pelayanan as $item) {
            $flaglab = 'N';
            $tglhasil = '';
            $tglcetak = '';
            $data = DB::select(DB::raw("SELECT distinct hh.flag, format(hh.tglhasil,'yyyy-MM-dd HH:mm') as tglhasil,  format(hh.tglcetak,'yyyy-MM-dd HH:mm') as tglcetak
            FROM pelayananpasien_t  as pp
            left join hasillaboratorium_t  as hh on hh.norecpelayanan  = pp.norec 
            where   pp.norec = '$item->norec_pp'"));


            // return($data);
            // die();
            foreach ($data as $pp) {
                if ($pp->flag == 'Y') {
                    $flaglab = $pp->flag;
                    $tglhasil = $pp->tglhasil;
                    $tglcetak = $pp->tglcetak;
                } else {
                    $tglhasil = $pp->tglhasil;
                    $tglcetak = $pp->tglcetak;
                }
            }
            $result[] = array(
                'nocm' => $item->nocm,
                'jeniskelamin' => $item->jeniskelamin,
                'tglpelayanan' => $item->tglpelayanan,
                'produkfk' => $item->produkfk,
                'umur' => $item->umur,
                'namaproduk' => $item->namaproduk,
                'noregistrasi' => $item->noregistrasi,
                'namaruangan' => $item->namaruangan,
                'namaruanganasal' => $item->namaruanganasal,
                'norec_apd' => $item->norec_apd,
                'tglhasil' => $tglhasil,
                'tglcetak' => $tglcetak,
                'norec_pp' => $item->norec_pp,
                'flaglab' => $flaglab,
                'iscito' => $item->iscito,
                'objectjeniskelaminfk' => $item->objectjeniskelaminfk,
                'tgllahir' => $item->tgllahir,
                'dokterpengirim' => $item->dokterpengirim,
                'dokterpemeriksa' => $item->dokterpemeriksa,
            );
        }

        $result = array(
            'data' => $result,
            'message' => 'inhuman',
        );

        return $this->respond($result);
