                        foreach ($isinaplastall as $itemianplastall) {
                            if($isinaplast->nosepinap == $itemianplastall->norujukan) {
                                $value->statusinaplast = true;
                                $value->nosepinap = $isinaplast->nosepinap;
                                $value->objectruanganinaplast = $isinaplast->objectruanganinaplast;
                            } else {
                                $value->statusinaplast = false;
                                $value->nosepinap = '-';
                                $value->objectruanganinaplast = '-';
                            }
                        }
                    } else {
                        $value->statusinaplast = false;
                        $value->nosepinap = '-';
                        $value->objectruanganinaplast = '-';
                    }
                } else {
                    $value->statusinaplast = false;
                    $value->nosepinap = '-';
                    $value->objectruanganinaplast = '-';
                }
            if($value->objectruanganlastfk == 132) {
                $ruanganrujuk = \DB::table('jadwalpraktekmingguan_m AS jpm')
                ->leftjoin('ruangan_m as ru', 'ru.id', '=', 'jpm.objectruanganfk')
                ->leftjoin('ruangankiosk_m as ruk', 'ruk.kodeexternal', '=', 'ru.id')
                ->where('ru.objectdepartemenfk', '<>', 132)
                ->where('jpm.objectpegawaifk', $value->pgid)
                ->select('ru.id as objectruangnrujukfk', 'ruk.kdinternal as kdinternalrujuk')
                ->first();
                // return($value);
                // die;
                // return($ruanganrujuk->objectruangnrujukfk);
                // die();
                if (!empty($ruanganrujuk)) {
                    // foreach ($diagnosa as $key2) {
                    //     // return($key2);
                    //     $value->isdiagnosis = $key2;
                    // }
                    $value->objectruangnrujukfk = $ruanganrujuk->objectruangnrujukfk;
                    $value->kdinternalrujuk = $ruanganrujuk->kdinternalrujuk;
                } else {
                    $value->objectruangnrujukfk = null;
                    $value->kdinternalrujuk = null;
                }
            } else {
                $value->objectruangnrujukfk = null;
                $value->kdinternalrujuk = null;
            }
            // if(strlen($value->norujukan) < 19) {
            $diagnosa = \DB::table('antrianpasiendiperiksa_t AS apd')
                ->join('detaildiagnosapasien_t AS ddp', 'ddp.noregistrasifk', '=', 'apd.norec')
                ->join('diagnosa_m as dg', 'dg.id', '=', 'ddp.objectdiagnosafk')
                ->where('ddp.objectjenisdiagnosafk', 1)
                ->where('apd.noregistrasifk', $value->norec)
                ->select('dg.namadiagnosa')
                ->first();
            if (!empty($diagnosa)) {
                foreach ($diagnosa as $key2) {
                    // return($key2);
                    $value->isdiagnosis = $key2;
                }
            } else {
                $value->isdiagnosis = false;
            }
            $data2[] =  $value;
            // }

            // $i = $i+1;
        }
        // return($data2);
        // die();

        for ($i = count($data2) - 1; $i >= 0; $i--) {
            if (isset($filter['isnotdiagnosis']) && $filter['isnotdiagnosis'] != "" && $filter['isnotdiagnosis'] != "undefined" && $filter['isnotdiagnosis'] != 'false' && $data2[$i]->isdiagnosis == true) {
                array_splice($data2, $i, 1);
            }
        }

        return $this->respond($data2);
    }

