    public function saveImage(Request $request)
    {

        $imageData = $request['photo'];
        $img = $request['photo'];
        $data = unpack("H*hex", $img);
        $data = '0x' . $data['hex'];
        Pasien::where('id', $request['id'])->update(
            ['foto' =>  \DB::raw("CONVERT(image, $data) ")]
        );
        $filteredData = substr($imageData, strpos($imageData, ",") + 1);
        $unencodedData = base64_decode($filteredData);

        //                $daritadi = Pasien::where('id',$request['id'])->first();
        //                $daritadi->foto =$data;
        //                $daritadi->save();
    }
    public function hapusPemakaianAsuransi(Request $request)
    {
        DB::beginTransaction();

        try {
            PemakaianAsuransi::where('norec', $request['norec'])
                ->delete();
            $transStatus = 'true';
        } catch (\Exception $e) {
            $transStatus = 'false';
        }

        if ($transStatus != 'false') {
            $transMessage = "Sukses";
            DB::commit();
            $result = array(
                "status" => 201,
                "message" => $transMessage,
            );
        } else {
            $transMessage = "Hapus Pemakaian Asuransi gagal";
            DB::rollBack();
            $result = array(
                "status" => 400,
                "message" => $transMessage,
            );
        }

        return $this->setStatusCode($result['status'])->respond($result, $transMessage);
    }
    public function saveMergeNoRM(Request $request)
    {
        DB::beginTransaction();

        try {
            $pasienAsal = Pasien::where('id', $request['idasal'])->update(
                ['statusenabled' => false]
            );
            $pasienTujuan = Pasien::where('nocm', $request['nocmtujuan'])
                ->where('statusenabled', true)
                ->first();
            if (empty($pasienTujuan)) {
                $transMessage = 'Pasien dengan RM ' .  $request['nocmtujuan'] . ' Tidak ada';
                $result = array(
                    'status' => 400,
                    'message' => $transMessage,
                    //                'data' => $pasienTujuan,
                    'as' => 'er@epic',
                );
                return $this->setStatusCode($result['status'])->respond($result, $transMessage);
            }
            $pasienDaftar = PasienDaftar::where('nocmfk',  $request['idasal'])->update([
                'nocmfk' =>  $pasienTujuan->id,
                'nocmmerge' => $request['nocmasal']
            ]);
            $emrPasien = EMRPasien::where('nocm',  $request['rmAsal'])->update([
                'nocm' =>  $pasienTujuan->nocm
            ]);
            $rekamMedis = RekamMedis::where('nocm',  $request['rmAsal'])->update([
                'nocm' =>  $pasienTujuan->nocm
            ]);
            $apr = AntrianPasienRegistrasi::where('nocmfk',  $request['idasal'])->update([
                'nocmfk' =>  $pasienTujuan->id,
            ]);
            $transStatus = true;
        } catch (\Exception $e) {
            $transStatus = false;
        }

        if ($transStatus == true) {
            DB::commit();
            $transMessage = 'Sukses ';
            $result = array(
                'status' => 201,
                'message' => $transMessage,
                //                'data' => $pasienTujuan,
                'as' => 'er@epic',
            );
        } else {
            $transMessage = 'Simpan Gagal ';
            DB::rollBack();
            $result = array(
                'status' => 400,
                'message' => $transMessage,
                //                'data' => $pasienTujuan,
                'as' => 'er@epic',
            );
        }
        return $this->setStatusCode($result['status'])->respond($result, $transMessage);
    }

    public function saveLoggingMergeNocm(Request $request)
    {
        DB::beginTransaction();
        $transStatus = true;
        $dataLogin = $request->all();
        // $alasan = '';
        // if (isset($request['alasanbatalclosing']) && $request['alasanbatalclosing'] != "" && $request['alasanbatalclosing'] != "undefined") {
        //     $alasan = $request['alasanbatalclosing'];
        // }
        // $pasienDaftar = PasienDaftar::where('noregistrasi', $request['noregistrasi'])->first();

        $newId = LoggingUser::max('id');
        $newId = $newId + 1;
        $logUser = new LoggingUser();
        $logUser->id = $newId;
        $logUser->norec = $logUser->generateNewId();
        $logUser->kdprofile = 0;
        $logUser->statusenabled = true;
        $logUser->jenislog = 'Merge NoCM';
        $logUser->noreff = $request['noregistrasi'];
        // $logUser->noreff = $pasienDaftar->noregistrasi;
        $logUser->referensi = 'Gabung Nomor Rekam Medis';
        $logUser->objectloginuserfk =  $dataLogin['userData']['id'];
        $logUser->tanggal = $this->getDateTime()->format('Y-m-d H:i:s');
        $logUser->keterangan = 'Gabung Nomor RM dari ' . $request['nocmasal'] . ' Ke Nomor RM ' . $request['nocmtujuan'];
        $logUser->save();

        if ($transStatus == true) {
            DB::commit();
            $result = array(
                "status" => 201,
                "message" => 'ea@epic'
            );
        } else {
            DB::rollBack();
            $result = array(
                "status" => 400,
                "message" => 'ea@epic'
            );
        }
        return $this->respond($result);
    }
