    public function getLaporanSummaryKunjunganger(Request $request)
    {

        $data = [];
        $tglAwal = $request['tglAwal'];
        $tglAkhir = $request['tglAkhir'];
        $ruanganId = $request['ruanganId'];
        $kelompokId = $request['kelompokPasien'];

        $paramRuangan = ' ';
        if (isset($ruanganId) && $ruanganId != "" && $ruanganId != "undefined") {
            // $paramRuangan = ' and pd.objectruanganlastfk = ' . $ruanganId;
            $paramRuangan = ' and ru.id = ' . $ruanganId;
        }

        $paramKelompok = ' ';
        if (isset($kelompokId) && $kelompokId != "" && $kelompokId != "undefined") {
            $paramKelompok = ' and pd.objectkelompokpasienlastfk = ' . $kelompokId;
        }

        $deptRawatJalan = $this->settingDataFixed('kdDepartemenRawatJalanFix');
            $data = DB::select(
            DB::raw(
                "select  ru.namaruangan, case when to_char(apd.tglregistrasi, 'MM') ='01' then 1 else 0 end  as jan,
                case when to_char(apd.tglregistrasi, 'MM')='02' then 1 else 0 end  as feb,
                case when to_char(apd.tglregistrasi, 'MM')='03' then 1 else 0 end  as mar,
                case when to_char(apd.tglregistrasi, 'MM')='04' then 1 else 0 end  as apr,
                case when to_char(apd.tglregistrasi, 'MM')='05' then 1 else 0 end  as mei,
                case when to_char(apd.tglregistrasi, 'MM')='06' then 1 else 0 end  as jun,
                case when to_char(apd.tglregistrasi, 'MM')='07' then 1 else 0 end  as jul,
                case when to_char(apd.tglregistrasi, 'MM')='08' then 1 else 0 end  as agus,
                case when to_char(apd.tglregistrasi, 'MM')='09' then 1 else 0 end  as sep,
                case when to_char(apd.tglregistrasi, 'MM')='10' then 1 else 0 end  as okt,
                case when to_char(apd.tglregistrasi, 'MM')='11' then 1 else 0 end  as nov,
                case when to_char(apd.tglregistrasi, 'MM')='12' then 1 else 0 end  as des
                ,dp.namadepartemen,ru.namaruangan,kp.kelompokpasien,CASE WHEN jk.id = 1 THEN 1 ELSE 0 END AS laki,
                CASE WHEN jk.id = 2 THEN 1 ELSE 0 END AS wanita,CASE WHEN pd.statuspasien = 'BARU' THEN 1 ELSE 0 END AS baru,
                CASE WHEN pd.statuspasien = 'LAMA' THEN 1 WHEN pd.statuspasien = '' THEN 1 ELSE 0 END AS lama from antrianpasiendiperiksa_t as apd left join pasiendaftar_t as pd on pd.norec = apd.noregistrasifk left join rekanan_m as rk on rk.id = pd.objectrekananfk left join ruangan_m as ru on ru.id = apd.objectruanganfk left join ruangan_m as ru2 on ru2.id = apd.objectruanganasalfk left join pasien_m as ps on ps.id = pd.nocmfk left join kelompokpasien_m as kp on kp.id = pd.objectkelompokpasienlastfk left join jeniskelamin_m as jk on jk.id = ps.objectjeniskelaminfk
                inner join departemen_m as dp on ru.objectdepartemenfk = dp.id     left JOIN ruangan_m AS rasal ON rasal.id = apd.objectruanganasalfk
	left JOIN departemen_m AS dp2 ON  dp.ID = rasal.objectdepartemenfk                 WHERE  pd.statusenabled = true  and apd.statusenabled = true and   apd.tglregistrasi >=  '$tglAwal' and apd.tglregistrasi <=  '$tglAkhir' 
               
                $paramRuangan $paramKelompok and dp.id in ($deptRawatJalan) and pd.statusenabled = true and apd.statusenabled = true and (apd.objectruanganasalfk is null or (apd.objectruanganasalfk is null or dp2.id in ($deptRawatJalan)) )
                and
                (DATE_PART('year', now()::timestamp )- DATE_PART('year',ps.tgllahir::timestamp) >60)"
            )
        );

    
        return $this->respond($data);
    }
