				CASE WHEN (x.bulan = 6 AND x.laki = 1) THEN SUM(x.laki) ELSE 0 END AS JunL,
				CASE WHEN (x.bulan = 7 AND x.laki = 1) THEN SUM(x.laki) ELSE 0 END AS JulL,
