    public function getSelisih($dateAwal, $dateAkhir)
    {
        $datetime = new \DateTime(date($dateAwal));
        return $datetime->diff(new \DateTime(date($dateAkhir)))
            ->format('%dhr %hjam %imnt');
    }
    public function getSensusHarianDetail(Request $request)
    {
        if ($request['setParam'] == 1) {
            $data = \DB::table('pasiendaftar_t as pd')
                ->leftjoin('antrianpasiendiperiksa_t as apd', 'apd.noregistrasifk', '=', 'pd.norec')
                ->leftjoin('pasien_m as ps', 'ps.id', '=', 'pd.nocmfk')
                ->leftjoin('jeniskelamin_m as jk', 'jk.id', '=', 'ps.objectjeniskelaminfk')
                ->leftjoin('ruangan_m as ru', 'ru.id', '=', 'pd.objectruanganlastfk')
                ->leftjoin('rekanan_m as rk', 'rk.id', '=', 'pd.objectrekananfk')
                ->leftjoin('kamar_m as km', 'km.id', '=', 'apd.objectkamarfk')
                ->leftjoin('tempattidur_m as tt', 'tt.id', '=', 'apd.nobed')
                ->leftjoin('kelas_m as kls', 'kls.id', '=', 'pd.objectkelasfk')
                ->select(DB::raw('ROW_NUMBER() OVER (ORDER BY ru.namaruangan) AS nomor,ru.id as id_ruangan,ru.namaruangan,
                        pd.tglregistrasi, pd.noregistrasi, ps.nocm, ps.namapasien, jk.jeniskelamin, rk.namarekanan,
                        km.namakamar, tt.reportdisplay, kls.namakelas'))
                ->where('pd.statusenabled', true)
                ->where('ps.objectjeniskelaminfk', '1')
                ->where('pd.objectrekananfk', '581368')
                ->where('pd.objectkelasfk', '8')
                ->whereNull('pd.tglpulang')
                ->whereNotNull('apd.objectkamarfk');
            if (isset($request['tglAwal']) && $request['tglAwal'] != "" && $request['tglAwal'] != "undefined") {
                $data = $data->where('pd.tglregistrasi', '>=', $request['tglAwal']);
            }
            if (isset($request['tglAkhir']) && $request['tglAkhir'] != "" && $request['tglAkhir'] != "undefined") {
