    public function getResponTimeTracerOnline(Request $request) {
        $tglAwal = $request['tglAwal'];
        $tglAkhir = $request['tglAkhir'];

        $data = DB::select(DB::raw("
        select x.namaruangan, sum(x.jumlahpasien) as jumlahpasien, convert(varchar(12),AVG(DATEDIFF(SECOND, x.tglregistrasi,x.tglperbandingan)/3600)) + 'j ' +
        convert(varchar(12),AVG(DATEDIFF(SECOND, x.tglregistrasi,x.tglperbandingan)%3600/60)) + 'm ' +
        convert(varchar(12),AVG(DATEDIFF(SECOND, x.tglregistrasi,x.tglperbandingan)%60)) + 'd ' as selisih from 
        (select ru.namaruangan,
        sum(case when pd.statusenabled = true then 1 else 0 end) as jumlahpasien, pd.tglregistrasi,kdr.tglkeluar, 
        case when pd.tglregistrasi < kdr.tglkeluar then kdr.tglkeluar else pd.tglregistrasi end as tglperbandingan ,
        convert(varchar(12),AVG(DATEDIFF(SECOND, pd.tglregistrasi,kdr.tglkeluar))) as detik
        from pasiendaftar_t as pd inner join
        antrianpasiendiperiksa_t as apd on apd.noregistrasifk = pd.norec inner join
        kendalidokumenrekammedis_t as kdr on kdr.noregistrasifk = apd.norec inner join
        antrianpasienregistrasi_t as apr on apr.noreservasi = pd.statusschedule and apr.nocmfk = pd.nocmfk inner join
        ruangan_m as ru on ru.id = apr.objectruanganfk
        where pd.tglregistrasi between '$tglAwal' and '$tglAkhir' and pd.statusschedule != 'Kios-K' and pd.statusschedule != '' and pd.statusschedule is not null and pd.statusenabled = true
        group by ru.namaruangan, pd.tglregistrasi, kdr.tglkeluar) as x
        group by x.namaruangan
        "));

        return $this->respond($data);
    }
