        and kdr.objectstatuskendalidokumenfk = 9
        group by ru.namaruangan, pd.tglregistrasi, kdr.tglupdate) as x
        "));

        return $this->respond($data);
    }
    
    public function getDataPasienPolda(Request $request)
    {
        $tglAwal = $request['tglAwal'];
        $tglAkhir = $request['tglAkhir'];
        $departemen = '';
        if (isset($request['departemenid']) && $request['departemenid'] != "" && $request['departemenid'] != "undefined") {
            $departemen = ' and ru.objectdepartemenfk = ' . $request['departemenid'];
        }
        
        $kesatuanpasien = '';
        if (isset($request['listkesatuan']) && $request['listkesatuan'] != "" && $request['listkesatuan'] != "undefined") {
            $kesatuanpasien = ' and ps.objectkesatuanfk IN (' . $request['listkesatuan'] . ')';
        }

        $data = DB::select(DB::raw("select
                kesatuanpasien,
                sum(jumlah) as jumlah,
                convert(decimal(8,3),(jumlah * 100.0 / sum (jumlah) over ())) as persen
                from(
                select 
                kesatuanpasien,
                count(kp.id) as jumlah,
                (kp.id * 100.0 / sum (kp.id) over ()) as persen,
                convert(decimal(8,3),count(*) * 100.0 / (select count(*)from pasiendaftar_t)) as persenn
                from pasien_m as ps inner join
                kesatuanpasien_m as kp on kp.id = ps.objectkesatuanfk inner join
                pasiendaftar_t as pd on pd.nocmfk = ps.id inner join
                ruangan_m as ru on pd.objectruanganlastfk = ru.id
                where pd.statusenabled = true and ps.objectkesatuanfk is not null
                and ps.objectpekerjaanfk = 6
                and pd.tglregistrasi between '$tglAwal' and '$tglAkhir' $departemen $kesatuanpasien group by  kp.kesatuanpasien, kp.id) as x
                group by x.jumlah, x.kesatuanpasien
        "));
        $datafix = [];
        foreach ($data as $item)
            $datafix[] = array(
                'namakesatuan' => $item->kesatuanpasien,
                'jumlah' => (float)$item->jumlah,
                'persen' => (float)$item->persen
            );
        return $this->respond($datafix);
    }
    
    public function getDataPasienPoldaSudahPulang(Request $request)
    {
        $data = \DB::table('pasiendaftar_t as pd')
            ->join('pasien_m as ps', 'ps.id', '=', 'pd.nocmfk')
            ->join('kesatuanpasien_m as kp', 'kp.id', '=', 'ps.objectkesatuanfk')
            ->leftjoin('pekerjaan_m as p', 'p.id', '=', 'ps.objectpekerjaanfk')
            ->leftjoin('rekanan_m as rk', 'rk.id', '=', 'pd.objectrekananfk')
            ->leftjoin('pangkat_m as ppl', 'ppl.id', '=', 'ps.pangkatpolisi')
            ->leftjoin('pangkat_m as pkt', 'pkt.id', '=', 'ps.pangkatpns')
            ->leftjoin('satuankerjapasien_m as skp', 'skp.id', '=', 'ps.objectsatuankerjafk')
            ->leftjoin('jeniskelompokpasien_m as jkp', 'jkp.id', '=', 'ps.objectjeniskelompokpasienfk')
            ->join('ruangan_m as ru', 'ru.id', '=', 'pd.objectruanganlastfk')
            ->select('ps.nocm', 'ps.namapasien', 'pd.noregistrasi', 'pd.tglregistrasi', 'kp.kesatuanpasien', 'skp.satuankerjapasien', 'ru.namaruangan', 'ppl.namapangkat as namapangkatpolisi', 'pkt.namapangkat', 'p.pekerjaan', 'rk.namarekanan', 'jkp.jeniskelompokpasien')
            // ->where('ps.objectpekerjaanfk', 6)
            // ->where('ru.objectdepartemenfk', 16)
            ->where('ps.objectjeniskelompokpasienfk', 1)
            ->where('pd.statusenabled', true)
            ->whereNotNull('pd.tglpulang')
            ->whereNotNull('ps.objectkesatuanfk');
        if (isset($request['tglAwal']) && $request['tglAwal'] != "" && $request['tglAwal'] != "undefined") {
            $data = $data->where('pd.tglregistrasi', '>=', $request['tglAwal']);
        }
        if (isset($request['tglAkhir']) && $request['tglAkhir'] != "" && $request['tglAkhir'] != "undefined") {
            $data = $data->where('pd.tglregistrasi', '<=', $request['tglAkhir']);
        }
        if (isset($request['kesatuan']) && $request['kesatuan'] != "" && $request['kesatuan'] != "undefined") {
            $data = $data->where('kp.kesatuanpasien', '=', $request['kesatuan']);
        }
        if (isset($request['departemenid']) && $request['departemenid'] != "" && $request['departemenid'] != "undefined") {
            $data = $data->where('ru.objectdepartemenfk', '=', $request['departemenid']);
        }
        if (isset($request['listkesatuan']) && $request['listkesatuan'] != "" && $request['listkesatuan'] != "undefined") {
            $data = $data->whereRaw(' ps.objectkesatuanfk IN (' . $request['listkesatuan'] . ')');
        }
        $data = $data->get();

        $result = array(
            'data' => $data,
            'message' => 'dats'
        );
        return $this->respond($result);
    }

