    public function cekNIKpasienBaru(Request $request)
    {
        $filter = $request->all();
        $data = \DB::table('pasien_m as ps')
            ->where('ps.statusenabled', '=', true)
            ->where('ps.id', '<>', $request['idnocm'])
            // ->where('ps.noidentitas','ilike', '%'.$request['noidentitas'].'%')
            ->where('ps.noidentitas', '=', $request['noidentitas']);
        if (isset($filter['norm']) && $filter['norm'] != "" && $filter['norm'] != "undefined") {
            $data = $data->where('ps.nocm', 'ilike', '%' . $filter['norm'] . '%');
        } else {
            $data = $data->where('ps.nocm', 'not ilike', '%P%');
            $data = $data->where('ps.nocm', 'not ilike', '%M%');
        }
        $data = $data->take(1);
        $data = $data->get();

        $result = array(
            'data' => $data,
            'message' => 'snaps',
        );

        return $this->respond($result);
    }
    public function getTitelPasienByTanggalLahir(Request $request)
    {

        $y   = $request['thnUmur'];
        $m   = $request['blnUmur'];
        $d   = $request['dayUmur'];

        // return($request['blnUmur']);
        // die();
        if ($y == 0) {

            if ($m == 0 & $d <= 28) {
                $data = DB::table('titlepasien_m')
                    ->select(DB::raw("id, UPPER(namaexternal) as titlepasien"))
                    ->where('statusenabled', true)
                    ->where('kelompoktitel', 'Bayi')
                    ->get();
            } else if ($m == 0 & $d > 28) {
                $data = DB::table('titlepasien_m')
                    ->select(DB::raw("id, UPPER(namaexternal) as titlepasien"))
                    ->where('statusenabled', true)
                    ->where('kelompoktitel', 'Anak')
                    ->get();
            } else {
                $data = DB::table('titlepasien_m')
                    ->select(DB::raw("id, UPPER(namaexternal) as titlepasien"))
                    ->where('statusenabled', true)
                    ->whereIn('kelompoktitel', array('Bayi', 'Anak'))
                    ->get();
            }
        } else if ($y <= 16) {
            $data = DB::table('titlepasien_m')
                ->select(DB::raw("id, UPPER(namaexternal) as titlepasien"))
                ->where('statusenabled', true)
                ->where('kelompoktitel', 'Anak')
                ->get();
        } else if ($y >= 17) {
            $data = DB::table('titlepasien_m')
                ->select(DB::raw("id, UPPER(namaexternal) as titlepasien"))
                ->where('statusenabled', true)
                ->where('kelompoktitel', 'Dewasa')
                ->get();
        }



        $result = array(
            'titlepasien' => $data,
            'message' => 'snaps',
        );
        return $this->respond($result);
    }
