    public function simpanMerge(Request $request)
    {
        DB::beginTransaction();
        try {




            $noRegTujuan = PasienDaftar::where('noregistrasi', $request['noRegTujuan'])->first();
            $noRegSalah = PasienDaftar::where('noregistrasi', $request['noRegSalah'])->first();
            if ($noRegTujuan->nocmfk != $noRegSalah->nocmfk) {
                $transMessage = 'Tidak Bisa Merge Registrasi , No.MR Berbeda !';
                return $this->setStatusCode(400)->respond([], $transMessage);
            }

            $data1 = AntrianPasienDiperiksa::where('noregistrasifk', $noRegSalah->norec)
                ->update([
                    'noregistrasifk' => $noRegTujuan->norec,
                    'noregistrasimerge' => $noRegSalah->norec,
                ]);
            $transStatus = 'true';
            $transMessage = "Merge Nomor Pendaftaran Berhasil...! ";
        } catch (\Exception $e) {
            $transStatus = 'false';
            $transMessage = "Gagal Simpan Data ...! ";
        }

        if ($transStatus != 'false') {
            DB::commit();
            $result = array(
                "status" => 201,
                "message" => $transMessage,
            );
        } else {
            DB::rollBack();
            $result = array(
                "status" => 400,
                "message" => $transMessage,
            );
        }

        // return 'sukses';
        return $this->setStatusCode($result['status'])->respond($result, $transMessage);
    }
