    public function getDaftarPasienRawat(Request $request)
    {

        $filter = $request->all();


        $norm = '';
        if (isset($filter['noRm']) && $filter['noRm'] != "" && $filter['noRm'] != "undefined") {
            $norm = " AND p.nocm ilike '%" .  $filter['noRm'] . "%'";
        }
        $namaPasien = '';
        if (isset($filter['namaPasien']) && $filter['namaPasien'] != "" && $filter['namaPasien'] != "undefined") {
            $namaPasien = " AND p.namapasien ilike '%" .  $filter['namaPasien'] . "%'";
        }
        $idPegawai = '';
        if (isset($filter['idPegawai']) && $filter['idPegawai'] != "" && $filter['idPegawai'] != "undefined") {
            $idPegawai = " AND pd.objectpegawaifk =" .  $filter['idPegawai'];
        }

        $data =  DB::select(DB::raw("
        select * from 
			                (
			select 
                pd.tglregistrasi,
                case when pd.tglpulang is not null then convert(varchar, pd.tglpulang, 120) else 'Masih Dirawat' end as tglpulang,
				p.nocm,
				pd.noregistrasi,
				ru.namaruangan,
				p.namapasien,
                kp.kelompokpasien,
                rk.namarekanan,
				kls.namakelas,
				alm.alamatlengkap,
				jk.jeniskelamin,
				pg.namalengkap AS namadokter,
                --case when ddp.objectjenisdiagnosafk != 1 then '-' when ddp.objectdiagnosafk is null then '-' else dg.namadiagnosa end as diagnosa,
				pd.norec AS norec_pd,
                --apd.norec AS norec_apd,
				pd.statuspasien,
				p.tgllahir,
				pd.objectruanganlastfk,
                pd.objectruanganasalfk,
                ru2.namaruangan as namaruanganasal,
				pd.objectkelasfk, apd.objectkamarfk,
				kmr.namakamar,apd.nobed,
                tt.reportdisplay as namabed,
                p.nobpjs
                
			FROM
				pasiendaftar_t AS pd
			INNER JOIN antrianpasiendiperiksa_t AS apd ON pd.norec = apd.noregistrasifk and pd.objectruanganlastfk = apd.objectruanganfk
			--inner join registrasipelayananpasien_t as rpp on rpp.noregistrasifk=pd.norec
			LEFT JOIN pasien_m AS p ON p.id = pd.nocmfk
			INNER JOIN ruangan_m AS ru ON ru.id = pd.objectruanganlastfk
            LEFT JOIN ruangan_m AS ru2 ON ru2.id = pd.objectruanganasalfk
			INNER JOIN kelas_m AS kls ON kls.id = pd.objectkelasfk
			INNER JOIN jeniskelamin_m AS jk ON jk.id = p.objectjeniskelaminfk
			LEFT JOIN pegawai_m AS pg ON pg.id = apd.objectpegawaifk
            LEFT JOIN kelompokpasien_m AS kp ON kp.id = pd.objectkelompokpasienlastfk
            LEFT JOIN rekanan_m AS rk ON rk.id = pd.objectrekananfk
			LEFT JOIN departemen_m AS dept ON dept.id = ru.objectdepartemenfk
			--LEFT JOIN batalregistrasi_t AS br ON pd.norec = br.pasiendaftarfk
			left JOIN kamar_m as kmr on kmr.id =apd.objectkamarfk
			left JOIN tempattidur_m as tt on tt.id =apd.nobed
			left join alamat_m as alm on alm.nocmfk = p.id
            --left join detaildiagnosapasien_t as ddp on ddp.noregistrasifk = apd.norec
            --left join diagnosa_m as dg on dg.id = ddp.objectdiagnosafk
            left join jeniskelompokpasien_m as jkp on jkp.id = p.objectjeniskelompokpasienfk
			where  pd.statusenabled = true
            and apd.statusenabled = true
		     $norm $namaPasien $idPegawai LIMIT 50
			) as x 
			order by x.tglregistrasi desc
		"));

        $data2 = [];
        foreach ($data as $key => $value) {
            $diagnosa = \DB::table('antrianpasiendiperiksa_t AS apd')
                ->join('detaildiagnosapasien_t AS ddp', 'ddp.noregistrasifk', '=', 'apd.norec')
                ->join('diagnosa_m as dg', 'dg.id', '=', 'ddp.objectdiagnosafk')
                ->where('ddp.objectjenisdiagnosafk', 1)
                ->where('apd.noregistrasifk', $value->norec_pd)
                ->select('dg.namadiagnosa')
                ->first();
            if (!empty($diagnosa)) {
                foreach ($diagnosa as $key2) {
                    // return($key2);
                    $value->isdiagnosis = $key2;
                }
            } else {
                $value->isdiagnosis = false;
            }
            $data2[] =  $value;

            // $i = $i+1;
        }
        for ($i = count($data2) - 1; $i >= 0; $i--) {
            if (isset($filter['isnotdiagnosis']) && $filter['isnotdiagnosis'] != "" && $filter['isnotdiagnosis'] != "undefined" && $filter['isnotdiagnosis'] != 'false' && $data2[$i]->isdiagnosis == true) {
                array_splice($data2, $i, 1);
            }
        }

        $result = array(
            'data' => $data2,
            'message' => 'ramdanegie',
        );
        return $this->respond($result);
    }
    public function getDaftarPasienRawatDua(Request $request)
    {

        $filter = $request->all();


