    public function getPasienMasukSentraVisum(Request $request)
    {
        $req = $request->all();
        $data = \DB::table('pasiendaftar_t as pd')
            ->join('antrianpasiendiperiksa_t as apd', 'apd.noregistrasifk', '=', 'pd.norec')
            ->join('pasien_m as ps', 'ps.id', '=', 'pd.nocmfk')
            ->join('jeniskelamin_m as jk', 'jk.id', '=', 'ps.objectjeniskelaminfk')
            ->join('pegawai_m as pg', 'pg.id', '=', 'apd.objectpegawaifk')
            ->join('kelompokpasien_m as kp', 'kp.id', '=', 'pd.objectkelompokpasienlastfk')
            ->join('rekanan_m as rk', 'rk.id', '=', 'pd.objectrekananfk')
            ->leftjoin('pasienvisum_t as pv', 'pv.noregistrasifk', '=', 'pd.norec')
            ->leftjoin('pegawai_m as pg2', 'pg2.id', '=', 'pv.dokterkonsultanfk')
            ->leftjoin('pegawai_m as pg3', 'pg3.id', '=', 'pv.dokterkonsultan2fk')
            ->leftjoin('pegawai_m as pg4', 'pg4.id', '=', 'pv.dokterkonsultan3fk')
            ->select(
                'pd.tglregistrasi',
                'pd.noregistrasi',
                'ps.nocm',
                'ps.namapasien',
                'ps.tgllahir',
                'pd.statuspasien',
                'pg.namalengkap',
                'pg.id as iddokter',
                'jk.jeniskelamin',
                'kp.kelompokpasien',
                'rk.namarekanan',
                'pd.norec as norec_pd',
                'apd.norec as norec_apd',
                'pv.draftvisum',
                'pv.draftriwayatkejadian',
                'pv.drafthasilpemeriksaan',
                'pv.draftkesimpulan',
                'pv.norec',
                'pv.catatan',
                DB::raw('case when pd.isvisum = 1 and pv.iskoreksii is null and pv.iskoreksiii is null and pv.isspesialis is null and pv.iskainstalasi is null and pv.isprint is null and pv.isdiserahkan is null then \'Draft Penulis\' when pv.iskoreksii = 1 then \'Koreksi I\'
                when pv.iskoreksiii = 1 then \'Koreksi Spesialis\' when pv.isspesialis = 1 then \'Koreksi Forensik\' when pv.iskainstalasi = 1 then \'Koreksi K.A Instalasi\' when pv.isprint = 1 then \'Print Admin\' when pv.isdiserahkan = 1 and pv.penerima is null then \'Belum Diambil\' when pv.isdiserahkan = 1 and pv.penerima is not null then \'Sudah Diambil\' else \'Terdaftar Di Visum\' end as status,
                case when pv.dokterkonsultanfk is null then \'Belum Input Dokter Konsulen\' else pg2.namalengkap end as dokterkonsultan, case when pv.dokterkonsultan2fk is null then \'Belum Input Dokter Konsulen\' else pg3.namalengkap end as dokterkonsultan2, case when pv.dokterkonsultan3fk is null then \'Belum Input Dokter Konsulen\' else pg4.namalengkap end as dokterkonsultan3')
            )
            ->where('pd.statusenabled', true)
            ->where('apd.statusenabled', true)
            ->where('apd.objectruanganfk', 251);
        if (isset($request['tglAwal']) && $request['tglAwal'] != "" && $request['tglAwal'] != "undefined") {
            $data = $data->where('apd.tglmasuk', '>=', $request['tglAwal']);
        }
        if (isset($request['tglAkhir']) && $request['tglAkhir'] != "" && $request['tglAkhir'] != "undefined") {
            $data = $data->where('apd.tglmasuk', '<=', $request['tglAkhir']);
        }
        if (isset($request['noreg']) && $request['noreg'] != "" && $request['noreg'] != "undefined") {
            $data = $data->where('pd.noregistrasi', '=', $request['noreg']);
        }
        if (isset($request['norm']) && $request['norm'] != "" && $request['norm'] != "undefined") {
            $data = $data->where('ps.nocm', 'ilike', '%' . $request['norm'] . '%');
        }
        if (isset($request['nama']) && $request['nama'] != "" && $request['nama'] != "undefined") {
            $data = $data->where('ps.namapasien', 'ilike', '%' . $request['nama'] . '%');
        }
        if (isset($request['idPegawai']) && $request['idPegawai'] != "" && $request['idPegawai'] != "undefined") {
            // $data = $data->where('pg.id', '=', $request['idPegawai']);
            $data = $data->Where(function ($data) use ($request) {
                $data->where('pg.id', '=', $request['idPegawai'])
                    ->orWhere('pv.dokterkonsultanfk', '=', $request['idPegawai'])
                    ->orWhere('pv.dokterkonsultan2fk', '=', $request['idPegawai'])
                    ->orWhere('pv.dokterkonsultan3fk', '=', $request['idPegawai']);
            });
        }
        $data = $data->get();

        return $this->respond($data);
    }
    public function savePasienToDraft(Request $request)
