    public function saveHasilSatuVisum(Request $request)
    {
        $dataLogin = $request->all();
        DB::beginTransaction();
        try {
            $updatePV = PasienVisum::where('noregistrasifk', $request['norec'])
                ->update([
                    'jeniskekerasanfk' => $request['jeniskekerasanfk'],
                    'penulisfk' => $request['penulisfk'],
