    public function getLoggingSentraVisum(Request $request)
    {
        $norec_pd = $request['norec_pd'];
        $data = DB::select(DB::raw(
            "select pg.namalengkap, log.jenislog, log.tanggal, pv.noregistrasifk from logginguser_t as log left join
            pasienvisum_t as pv on pv.noregistrasifk = log.noreff left join
            loginuser_s as lgu on lgu.id = log.objectloginuserfk left join
            pegawai_m as pg on pg.id = lgu.objectpegawaifk
            where log.jenislog = 'Draft Penulis' and pv.noregistrasifk = '$norec_pd' 
            or log.jenislog = 'Draft Penulis To Koreksi I' and pv.noregistrasifk = '$norec_pd' 
            or log.jenislog = 'Koreksi I to Koreksi Spesialis' and pv.noregistrasifk = '$norec_pd' 
            or log.jenislog = 'Koreksi Spesialis to Koreksi Forensik' and pv.noregistrasifk = '$norec_pd' 
            or log.jenislog = 'Koreksi Forensik to KA Instalasi' and pv.noregistrasifk = '$norec_pd'
            or log.jenislog = 'Koreksi KA Instalasi To Print Admin' and pv.noregistrasifk = '$norec_pd'"
        ));
        return $this->respond($data);
    }
