        }
        if (isset($request['noreg']) && $request['noreg'] != "" && $request['noreg'] != "undefined") {
            $data = $data->where('pd.noregistrasi', '=', $request['noreg']);
        }
        if (isset($request['nocm']) && $request['nocm'] != "" && $request['nocm'] != "undefined") {
            $data = $data->where('ps.nocm', 'ilike', '%' . $request['nocm'] . '%');
        }
        if (isset($request['nama']) && $request['nama'] != "" && $request['nama'] != "undefined") {
            $data = $data->where('ps.namapasien', 'ilike', '%' . $request['nama'] . '%');
        }
        $data = $data->get();

        return $this->respond($data);
    }

    public function getHistoryNoregistrasi(Request $request)
    {
        $data = \DB::table('pasien_m as ps')
            ->join('pasiendaftar_t as pd', 'pd.nocmfk', '=', 'ps.id')
            ->join('ruangan_m as ru', 'ru.id', '=', 'pd.objectruanganlastfk')
            ->select('ps.nocm', 'ps.namapasien', 'pd.noregistrasi', 'ru.namaruangan', 'pd.tglregistrasi', 'pd.norec')
            ->where('pd.statusenabled', true)
            ->where('ps.nocm', $request['nocm'])
            ->orderBy('pd.tglregistrasi', 'DESC')
            ->get();

        $result = array(
            'data' => $data,
            'message' => 'ramdanegie',
        );
        return $this->respond($result);
    }

    public function simpanCatatan(Request $request) {
        $dataLogin = $request->all();
        DB::beginTransaction();
        try {
            $updatePV = PasienVisum::where('norec', $request['norec'])
                ->update([
                    'catatan' => $request['catatan'], 
                ]);
            $transMessage = "Sukses !";

            $transStatus = 'true';

            if ($transStatus == 'true') {
                $newLog = LoggingUser::max('id');
                $newLog = $newLog + 1;
                $logUser = new LoggingUser();
                $logUser->id = $newLog;
                $logUser->norec = $logUser->generateNewId();
                $logUser->kdprofile = 0;
                $logUser->statusenabled = true;
                $logUser->jenislog = 'Simpan Catatan';
                $logUser->noreff = $request['noregistrasi'];
                $logUser->referensi = 'noregistrasi Pasien Daftar';
                $logUser->keterangan = 'Simpan Catatan No Registrasi : ' . $request['noregistrasi'];
                $logUser->objectloginuserfk = $dataLogin['userData']['id'];
                $logUser->tanggal = $this->getDateTime()->format('Y-m-d H:i:s');
                $logUser->save();
            };
        } catch (\Exception $e) {
            $transStatus = 'false';
        }

        if ($transStatus == 'true') {

            DB::commit();
            $result = array(
                "status" => 201,
                "message" => $transMessage,
                "as" => 'as@epic',
            );
        } else {
            $transMessage = "Gagal !";
            DB::rollBack();
            $result = array(
                "status" => 400,
                "message" => $transMessage,
                "as" => 'as@epic',
            );
        }
        return $this->setStatusCode($result['status'])->respond($result, $transMessage);
    }
    public function getCatatanVisum(Request $request) {
        $data = \DB::table('pasienvisum_t as pv')
            ->select('pv.catatan')
            ->where('pv.norec', $request['norec'])
            ->get();

            return $this->respond($data);
    }
    public function getAngkaTitik(Request $request) {
        $data = \DB::table('tempangka_t as ta')
            ->select('ta.angka');
            if (isset($request['variabel']) && $request['variabel'] != "" && $request['variabel'] != "undefined") {
                $data = $data->where('ta.namavariabel', '=', $request['variabel']);
            }
            if (isset($request['length']) && $request['length'] != "" && $request['length'] != "undefined") {
                $data = $data->where('ta.length', '=', $request['length']);
            };
            $data = $data->get();

            return $this->respond($data);
    }
    public function saveListNoControlNSPRIFromBPJS(Request $request)
    {
        DB::beginTransaction();
        try {
            foreach ($request['data']['list'] as $item) {
                $data = ListRencanaKontroldanSPRI::where('noSuratKontrol', $item['noSuratKontrol'])->first();
    
                if ($data == null) {
                    $dataNoControlNSPRI = new ListRencanaKontroldanSPRI();
                    $dataNoControlNSPRI->norec = $dataNoControlNSPRI->generateNewId();
                    $dataNoControlNSPRI->statusenabled = true;
                } else {
                    $dataNoControlNSPRI = ListRencanaKontroldanSPRI::where('noSuratKontrol', $item['noSuratKontrol'])->first();
                }
                $dataNoControlNSPRI->jnsKontrol = $item['jnsKontrol'];
                $dataNoControlNSPRI->jnsPelayanan = $item['jnsPelayanan'];
                $dataNoControlNSPRI->kodeDokter = $item['kodeDokter'];
                $dataNoControlNSPRI->nama = $item['nama'];
                $dataNoControlNSPRI->namaDokter = $item['namaDokter'];
                $dataNoControlNSPRI->namaJnsKontrol = $item['namaJnsKontrol'];
                $dataNoControlNSPRI->namaPoliAsal = $item['namaPoliAsal'];
                $dataNoControlNSPRI->namaPoliTujuan = $item['namaPoliTujuan'];
                $dataNoControlNSPRI->noKartu = $item['noKartu'];
                $dataNoControlNSPRI->noSepAsalKontrol = $item['noSepAsalKontrol'];
                $dataNoControlNSPRI->noSuratKontrol = $item['noSuratKontrol'];
                $dataNoControlNSPRI->poliAsal = $item['poliAsal'];
                $dataNoControlNSPRI->poliTujuan = $item['poliTujuan'];
                $dataNoControlNSPRI->terbitSEP = $item['terbitSEP'];
                $dataNoControlNSPRI->tglRencanaKontrol = $item['tglRencanaKontrol'];
                $dataNoControlNSPRI->tglSEP = $item['tglSEP'];
                $dataNoControlNSPRI->tglTerbitKontrol = $item['tglTerbitKontrol'];
                $dataNoControlNSPRI->save();
                // return(count($data));
                // die();
            }
            $transStatus = 'true';
        } catch (\Exception $e) {
            $transStatus = 'false';
            $transMessage = "Simpan No Kontrol dan SPRI Gagal ";
        }

        if ($transStatus == 'true') {
            $transMessage = "Simpan Berhasil";
            DB::commit();
            $result = array(
                'status' => 201,
                'message' => $transMessage,
                'as' => 'ramdanegie',
            );
        } else {
            $transMessage = "Simpan Gagal";
            DB::rollBack();
            $result = array(
                'status' => 400,
                'message'  => $transStatus,
                'as' => 'ramdanegie',
            );
        }
        return $this->setStatusCode($result['status'])->respond($result, $transMessage);
    }
